import logging
import re
import time

from taf.sw.wtssim import wtssim  # type: ignore[import-untyped]


def ensure_all_components_are_activated(timeout: float, wtssim: wtssim, alias: str, logger: logging.Logger, check_version=True) -> None:
    STATE_SIM_DISP_REGEX = re.compile(r"(?P<device>[\w-]+)[^a-zA-Z]+(?P<type>\w+|-)\s+(?P<id>\d+|-)\s+(?P<link>\w+|-)\s+(?P<state>\w+|-)")
    start_time = time.time()
    while (time.time() - start_time) < timeout:
        state_sim_disp = execute_wtssim_command("state_sim_disp", wtssim, alias, logger)
        for match in STATE_SIM_DISP_REGEX.finditer(state_sim_disp):
            if match.group("type") == "simulated":
                state = match.group("state").lower().strip()
                if state == "active":
                    continue
                elif state == "init":
                    execute_wtssim_command(f"start version_check={'on' if check_version else 'off'}", wtssim, alias, logger, False)
                break
        else:
            logger.info("All components are ACTIVE")
            return
        time.sleep(5)
    else:
        raise EpcsimComponentsNotActive()


def get_cells_from_external_enbs(wtssim: wtssim, alias: str, logger: logging.Logger) -> dict[int, dict[str, dict]]:
    CELL_ID_REGEXP = re.compile(r"cell (?P<id>\d+)")
    CELL_PARAM_VALUE_REGEXP = re.compile(r"(?P<param>[\w \-()/_]+?)\s{2,}(?P<value>[\w.() :]+?)\s{2,}")
    external_enbs = get_external_enbs_from_egate_output(wtssim, alias, logger)
    cells_data: dict[int, dict[str, dict]] = {}
    for enb in external_enbs:
        cells_data[enb] = {"enb": {}}
        cell_id = "enb"
        data = execute_wtssim_command(f"enb_disp type=cell_info id={enb}", wtssim, alias, logger)
        for line in (line.lower() for line in data.split("\r\n")[4:] if line):
            match = CELL_ID_REGEXP.search(line)
            if match:
                cell_id = match.group("id")
                cells_data[enb][cell_id] = {}
                continue
            match = CELL_PARAM_VALUE_REGEXP.search(line)
            if match:
                cells_data[enb][cell_id].update({match.group("param"): match.group("value")})
    return cells_data


def get_external_enbs_from_egate_output(wtssim: wtssim, alias: str, logger: logging.Logger) -> list[int]:
    data = execute_wtssim_command("enb_disp type=cell_info", wtssim, alias, logger)
    ENB_REGEXP = re.compile(r"(?P<id>\d+).*?(?P<type>external)")
    external_enbs = [int(match.group("id")) for match in ENB_REGEXP.finditer(data)]
    logger.debug(f"External eNBs found: {external_enbs}")
    return external_enbs


def execute_wtssim_command(cmd: str, wtssim: wtssim, alias: str, logger: logging.Logger, output: bool = True) -> str:
    logger.debug(f"Executing wtssim command '{cmd}' with alias '{alias}'")
    data = ""
    if output:
        data = wtssim.execute_egate_command_and_wait_for_data(cmd, alias=alias)
        logger.debug(f"Output for command '{cmd}': {data}")
    else:
        wtssim.execute_egate_command(cmd, alias=alias)
    return data


class EpcsimComponentsNotActive(Exception):
    pass
